def word_frequency(text: str) -> dict[str, int]:
    import string

    result: dict[str, int] = {}
    for raw_word in text.split():
        word = raw_word.strip(string.punctuation).lower()
        if word:
            result[word] = result.get(word, 0) + 1
    return result
